presets.prompt:
{subject}, {
  "image_generation_prompt": {
    "overall_style": "一个高度复杂、概念化的数字拼贴插画，将一个孤独的人物与激进的数字故障和模拟印刷失真纹理融合在一起，并对触感表面进行了深度细致的聚焦。整体美学是漫画风格线条艺术与原始、破旧的后人类/赛博故障感的融合。",
    "composition": "一个单一的、居中构图的人物，从略微倾斜的前侧视图观察。构图建立在沉重的水平和垂直分割之上。",
    "figure_details": {
      "subject": "一个孤独的年轻女性/女孩。她的形象部分是深色剪影，部分是清晰的线条艺术，正经历着文字和几何的消解过程。",
      "pose": "静止站立，头部微转，目光被遮挡，右手（在左侧可见）在髋部附近握着一个物体（部分被遮挡）。",
      "clothing": {
        "description": "一套传统的日本水手服（seifuku）。",
        "parts": [
          "衬衫的上半部分及其带有白色丝带领结的黑色水手领定义清晰，但它们的表面具有沉重纹理，带有原始、破旧的印刷伪影颗粒。",
          "领口下方的白色上衣主体过渡到一个严重的故障和文本消解区域，由纹理数据块和水平信号线组成。",
          "深色百褶裙（制服的下半部分）可见，但呈现于深邃的阴影中，几乎完全黑暗，被一种丝绸般的、墨色的纹理所掩盖，水平和垂直的数据块以及细碎的白色信号线融入黑暗之中。"
        ]
      },
      "hair": "深色、剪影般的头发，带有凌乱、自由流动的发丝，同样正在经历纹理降解并被故障面板切断。",
      "head_obscuration": "一个显眼的、长方形的面板，由柔和、有纹理的粉色/三文鱼色类纸材料制成，略微透明且带有可见的纤维纹理，水平放置在她的脸上，完全遮住了她的眼睛。边缘清晰但略有磨损。"
    },
    "distortion_and_glitch_elements": {
      "description": "整个图像由广泛的几何和文本故障叠加层构成。",
      "panels_and_blocks": [
        "多块独特的、有纹理的白色和浅灰色纸质纹理块层叠在人物的头部和身体周围，特别是在左侧和右下方，显示出颜料积聚和破损的印刷边缘。",
        "一个黑色的、重纹理的数据块（数据烟雾）位于她头部的右侧，融入一片颗粒状数据点云中。",
        "小型、孤立的黑色数据块散布在各处，特别是在黑暗的下半部分。",
        "在她左下方的手附近可见一个小的、有纹理的方块。"
      ],
      "data_lines": [
        "由极细的、薄薄的垂直和水平白色及灰色信号干扰线和扫描线组成的网络在整个构图中创建了一个精确的网格，特别是在黑暗的虚空和她的下半身制服上。",
        "这些线条形成了微小的数据点星座，就像微弱的数字星星。"
      ],
      "figure_dissolution": "从坚实的制服到黑暗虚空的过渡是凌乱的，由数据烟雾和水平数据段组成，使她的下半身看起来消解在数字噪音中。"
    },
    "background": {
      "description": "背景分为三个截然不同的、破旧的水平带。",
      "sky": "顶部是一个苍白的、冷色调的灰蓝色天空面板，具有细微的云状纹理和破损边缘，显示出水平和垂直扫描线。",
      "ocean": "中间带是深邃、有纹理的深蓝色大海，带有积聚的水渍和破旧的印刷伪影，显示出带有沉重颗粒的破碎波浪。",
      "void": "下半部分是一个巨大的、深邃的哑光黑色虚空般空间，厚厚地堆叠着细线数据网格和零散的有纹理的数据块。"
    },
    "textural_and_film_grain": "普遍的、沉重的、原始的胶片颗粒和纸张般的纹理覆盖了整个图像，使所有表面具有一种触手可及的、类似印刷品的感觉。所有面板的边缘都不是锋利的，而是表现出纸张磨损和印刷伪影。 subtle puddled pigment effects are visible in the watercolor-like sea panel and pink block.",
    "lighting_and_color_palette": {
      "lighting": "低调且充满氛围感，冷色调的光线勾勒出人物清晰的线条。主要光源是苍白的天空和粉色色块，它们投射出细微的冷色调。",
      "color_palette": ["虚空黑", "深海军蓝", "柔和粉/三文鱼色", "苍灰蓝色", "纹理白", "深灰色", "墨水、纸张和油漆的破损纹理。"]
    },
    "atmosphere": "极其忧郁、内省、数据驱动但又具机理感，探索数字腐朽与后人类身份的交汇。"
  }
}

